const businessNameCounter = document.getElementById('businessNameCounter');
const businessNameWarning = document.getElementById('businessNameWarning');

// Set max length attribute
businessNameInput.setAttribute('maxlength', '26');

// Update counter on input
businessNameInput.addEventListener('input', function() {
    const currentLength = this.value.length;
    const maxLength = 26;
    
    // Update counter text - keep as is since it's dynamic
    businessNameCounter.textContent = `${currentLength}/${maxLength} ${translate('characters')}`;
    
    // Show warning if near or at limit
    if (currentLength >= maxLength) {
        businessNameCounter.classList.add('text-red-500', 'font-bold');
        businessNameCounter.classList.remove('text-gray-500');
        businessNameWarning.classList.remove('hidden');
        showMessageModal(translate('business_name_max_length'));
        
        // Prevent further input if somehow exceeds
        if (currentLength > maxLength) {
            this.value = this.value.substring(0, maxLength);
        }
    } else if (currentLength >= maxLength - 5) {
        // Warning when approaching limit
        businessNameCounter.classList.add('text-orange-500', 'font-medium');
        businessNameCounter.classList.remove('text-gray-500', 'text-red-500', 'font-bold');
        businessNameWarning.classList.add('hidden');
    } else {
        // Normal state
        businessNameCounter.classList.remove('text-red-500', 'text-orange-500', 'font-bold', 'font-medium');
        businessNameCounter.classList.add('text-gray-500');
        businessNameWarning.classList.add('hidden');
    }
});

// Also check on page load if there's already a value
if (businessNameInput.value) {
    businessNameInput.dispatchEvent(new Event('input'));
}

// Prevent paste from exceeding limit
businessNameInput.addEventListener('paste', function(e) {
    const pastedText = e.clipboardData.getData('text');
    const currentText = this.value;
    const newText = currentText + pastedText;
    
    if (newText.length > 25) {
        e.preventDefault();
        // Only allow paste up to the limit
        const allowedPaste = pastedText.substring(0, 25 - currentText.length);
        this.value = currentText + allowedPaste;
        // Trigger input event to update counter
        this.dispatchEvent(new Event('input'));
    }
});

function initializeBusinessDetailsCounter() {
    const businessDetailsInput = document.getElementById('businessDetailsInput');
    const businessDetailsCounter = document.getElementById('businessDetailsCounter');
    
    if (!businessDetailsInput || !businessDetailsCounter) return;

    updateBusinessDetailsCounter();
    businessDetailsInput.addEventListener('input', updateBusinessDetailsCounter);
    
    function updateBusinessDetailsCounter() {
        const currentLength = businessDetailsInput.value.length;
        const maxLength = 159;
        
        // Update counter text - keep as is since it's dynamic
        businessDetailsCounter.textContent = `${currentLength}/${maxLength}`;
        
        // Change color if approaching or exceeding limit
        if (currentLength >= maxLength) {
            businessDetailsCounter.classList.remove('text-gray-500', 'text-yellow-500');
            businessDetailsCounter.classList.add('text-red-500', 'font-bold');
            showMessageModal(translate('business_details_max_length'));
        } else if (currentLength >= maxLength - 10) { // Last 10 characters
            businessDetailsCounter.classList.remove('text-gray-500', 'text-red-500');
            businessDetailsCounter.classList.add('text-yellow-500');
        } else {
            businessDetailsCounter.classList.remove('text-red-500', 'text-yellow-500', 'font-bold');
            businessDetailsCounter.classList.add('text-gray-500');
        }
    }
}




function showBusinessInfoPrompt() {
    return new Promise((resolve) => {
        const modal = document.getElementById('businessInfoModal');
        const emailInput = document.getElementById('businessEmailInput');
        const websiteInput = document.getElementById('businessWebsiteInput');
        const confirmBtn = document.getElementById('businessInfoConfirmBtn');
        const cancelBtn = document.getElementById('businessInfoCancelBtn');
        
        // Clear previous values
        emailInput.value = '';
        websiteInput.value = '';
        
        // Show modal and add 'active' class
        modal.classList.remove('hidden');
        modal.classList.add('active');  // Add active class for styling
        emailInput.focus();
        
        const cleanup = () => {
            modal.classList.add('hidden');
            modal.classList.remove('active');
            confirmBtn.removeEventListener('click', confirmHandler);
            cancelBtn.removeEventListener('click', cancelHandler);
            emailInput.removeEventListener('keypress', keyHandler);
        };
        
        const confirmHandler = () => {
            const email = emailInput.value.trim();
            const website = websiteInput.value.trim();
            
            if (!email) {
                // Show error inside modal
                const errorMsg = document.createElement('p');
                errorMsg.className = 'text-red-500 text-sm mt-2';
                errorMsg.innerText = translate('email_required') || 'Email is required.';
                modal.querySelector('.bg-white').appendChild(errorMsg);
                setTimeout(() => errorMsg.remove(), 2000);
                emailInput.focus();
                return;
            }
            
            if (!email.includes('@')) {
                const errorMsg = document.createElement('p');
                errorMsg.className = 'text-red-500 text-sm mt-2';
                errorMsg.innerText = translate('invalid_email_format') || 'Please enter a valid email address.';
                modal.querySelector('.bg-white').appendChild(errorMsg);
                setTimeout(() => errorMsg.remove(), 2000);
                emailInput.focus();
                return;
            }
            
            cleanup();
            resolve({ email, website });
        };
        
        const cancelHandler = () => {
            cleanup();
            resolve(null);
        };
        
        const keyHandler = (e) => {
            if (e.key === 'Enter') confirmHandler();
        };
        
        confirmBtn.addEventListener('click', confirmHandler);
        cancelBtn.addEventListener('click', cancelHandler);
        emailInput.addEventListener('keypress', keyHandler);
    });
}

// ===== calutor.js =====
// calutor.js - Draggable Keyboard Calculator

class DraggableCalculator {
    constructor() {
        this.display = null;
        this.calculator = null;
        this.calculatorHeader = null;
        this.closeBtn = null;
        this.buttons = null;
        
        this.isDragging = false;
        this.dragOffsetX = 0;
        this.dragOffsetY = 0;
        
        // Check if DOM is already loaded
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', () => this.initcalcultr());
        } else {
            this.initcalcultr();
        }
    }
    
    initcalcultr() {
        this.createCalculatorHTML();
        this.setupElements();
        this.setupEventListeners();
        this.setupGlobalStyles();
    }
    
    createCalculatorHTML() {
        // Prevent creating duplicates
        if (document.querySelector('.calculator')) return;

        const calculatorHTML = `
            <div class="calculator rounded-2xl shadow-2xl overflow-hidden">
                <div class="calculator-header bg-gradient-to-r from-violet-600 to-indigo-600 text-white">
                    <span class="text-xs font-medium">Drag here to move</span>
                    <button class="close-btn hover:text-red-300">×</button>
                </div>
                
                <div class="glass-effect p-6">
                    <input type="text" class="display w-full h-16 mb-4 px-4 text-right text-3xl font-semibold rounded-xl bg-gradient-to-r from-gray-900 to-gray-800 text-white border-2 border-gray-700 focus:outline-none focus:border-indigo-500 shadow-inner" id="display" disabled />
                    
                    <div class="grid grid-cols-4 gap-3">
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-rose-500 to-pink-600 text-white font-medium text-lg hover:from-rose-600 hover:to-pink-700 active:scale-95 shadow-lg" data-action="clear">C</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 text-white font-medium text-lg hover:from-emerald-600 hover:to-teal-700 active:scale-95 shadow-lg" data-action="divide">÷</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 text-white font-medium text-lg hover:from-emerald-600 hover:to-teal-700 active:scale-95 shadow-lg" data-action="multiply">×</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 text-white font-medium text-lg hover:from-emerald-600 hover:to-teal-700 active:scale-95 shadow-lg" data-action="subtract">−</button>

                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="7">7</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="8">8</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="9">9</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-amber-500 to-orange-500 text-white font-medium text-lg hover:from-amber-600 hover:to-orange-600 active:scale-95 shadow-lg row-span-2" data-action="add">+</button>

                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="4">4</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="5">5</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="6">6</button>

                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="1">1</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="2">2</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="3">3</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-violet-500 to-purple-600 text-white font-medium text-lg hover:from-violet-600 hover:to-purple-700 active:scale-95 shadow-lg row-span-2" data-action="equals">=</button>

                        <button class="col-span-2 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-value="0">0</button>
                        <button class="col-span-1 h-14 rounded-xl bg-gradient-to-br from-slate-700 to-slate-800 text-white font-medium text-lg hover:from-slate-800 hover:to-slate-900 active:scale-95 shadow-md" data-action="decimal">.</button>
                    </div>
                </div>
            </div>
        `;
        document.body.insertAdjacentHTML('beforeend', calculatorHTML);
    }
    
    setupElements() {
        this.display = document.getElementById('display');
        this.calculator = document.querySelector('.calculator');
        this.calculatorHeader = document.querySelector('.calculator-header');
        this.closeBtn = this.calculatorHeader.querySelector('.close-btn');
        this.buttons = document.querySelectorAll('.calculator button[data-value], .calculator button[data-action]');
    }

    setupGlobalStyles() {
        if(document.getElementById('calc-styles')) return;

        const style = document.createElement('style');
        style.id = 'calc-styles';
        style.textContent = `
            .calculator {
                display: none;
                cursor: move;
                position: fixed;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                z-index: 9999999999999999999999999999999999999999999999; /* High z-index to ensure it shows on top */
                user-select: none;
                backdrop-filter: blur(10px);
                max-width: 90vw;
                width: 320px;
            }

            .calculator.show {
                display: block;
                animation: fadeIn 0.3s ease-out;
            }

            .calculator.dragging {
                opacity: 0.9;
                cursor: grabbing;
            }

            .calculator-header {
                position: relative; /* Fixed from absolute to relative for better layout */
                height: 30px;
                border-radius: 5px 5px 0 0;
                display: flex;
                align-items: center;
                justify-content: space-between;
                padding: 0 10px;
                cursor: move;
            }

            .close-btn {
                background: none;
                border: none;
                font-size: 20px;
                font-weight: bold;
                cursor: pointer;
            }

            @keyframes fadeIn {
                from { opacity: 0; transform: translate(-50%, -50%) scale(0.95); }
                to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
            }

            .glass-effect {
                background: rgba(30, 41, 59, 0.85); /* Darker background for visibility */
                backdrop-filter: blur(10px);
                border: 1px solid rgba(255, 255, 255, 0.1);
            }
           @media print {
                .calculator {
                    display: none !important;
                }
            }     
        `;
        document.head.appendChild(style);
    }
    
    setupEventListeners() {
        // Apply passive: true to ALL touch listeners
        this.setupPassiveTouchListeners();
        
        // Button click listeners
        this.buttons.forEach(button => {
            button.addEventListener('click', (e) => {
                e.preventDefault();
                const value = button.getAttribute('data-value');
                const action = button.getAttribute('data-action');
                if (value) this.appendToDisplay(value);
                else if (action) this.handleAction(action);
            }, { passive: true });
        });
        
        // Close button
        this.closeBtn.addEventListener('click', () => this.closeCalculator(), { passive: true });
        
        // Mouse dragging
        this.calculatorHeader.addEventListener('mousedown', (e) => this.startDragging(e), { passive: true });
        document.addEventListener('mousemove', (e) => this.doDragging(e));
        document.addEventListener('mouseup', () => this.stopDragging(), { passive: true });
        
        // Keyboard
        document.addEventListener('keydown', (e) => this.handleKeyboard(e), { passive: true });
    }
    
    setupPassiveTouchListeners() {
        // Fix all touch event listeners with passive: true
        this.calculatorHeader.addEventListener('touchstart', (e) => {
            if (e.touches.length !== 1) return;
            e.preventDefault();
            this.startDraggingTouch(e);
        }, { passive: false }); // Only touchstart needs non-passive for preventDefault
        
        document.addEventListener('touchmove', (e) => {
            if (!this.isDragging || e.touches.length !== 1) return;
            e.preventDefault();
            this.doDraggingTouch(e);
        }, { passive: false }); // Only touchmove needs non-passive for preventDefault
        
        document.addEventListener('touchend', () => {
            this.stopDragging();
        }, { passive: true });
        
        // Make all other touch listeners passive
        this.buttons.forEach(button => {
            button.addEventListener('touchstart', (e) => {
                e.preventDefault();
                const value = button.getAttribute('data-value');
                const action = button.getAttribute('data-action');
                if (value) this.appendToDisplay(value);
                else if (action) this.handleAction(action);
            }, { passive: false });
        });
    }
    
    // Logic Methods
    appendToDisplay(value) {
        this.display.value += value;
        this.display.scrollLeft = this.display.scrollWidth;
    }
    
    clearDisplay() {
        this.display.value = '';
    }
    
    calculate() {
        try {
            let expression = this.display.value.replace(/×/g, '*').replace(/÷/g, '/');
            if (expression === '') return;
            // Safer eval alternative using Function
            this.display.value = new Function('return ' + expression)();
        } catch (error) {
            this.display.value = 'Error';
            setTimeout(() => this.clearDisplay(), 1500);
        }
    }
    
    closeCalculator() {
        this.calculator.classList.remove('show');
        this.clearDisplay();
    }
    
    handleAction(action) {
        switch(action) {
            case 'clear': this.clearDisplay(); break;
            case 'equals': this.calculate(); break;
            case 'add': this.appendToDisplay('+'); break;
            case 'subtract': this.appendToDisplay('-'); break;
            case 'multiply': this.appendToDisplay('×'); break;
            case 'divide': this.appendToDisplay('÷'); break;
            case 'decimal': this.appendToDisplay('.'); break;
        }
    }
    
    // Dragging Logic
    startDragging(e) {
        e.preventDefault();
        this.isDragging = true;
        this.calculator.classList.add('dragging');
        const rect = this.calculator.getBoundingClientRect();
        this.dragOffsetX = e.clientX - rect.left;
        this.dragOffsetY = e.clientY - rect.top;
    }
    
    doDragging(e) {
        if (!this.isDragging) return;
        e.preventDefault();
        const x = e.clientX - this.dragOffsetX;
        const y = e.clientY - this.dragOffsetY;
        this.calculator.style.left = `${x}px`;
        this.calculator.style.top = `${y}px`;
        this.calculator.style.transform = 'none';
    }
    
    stopDragging() {
        this.isDragging = false;
        if(this.calculator) this.calculator.classList.remove('dragging');
    }

    startDraggingTouch(e) {
        if (e.touches.length !== 1) return;
        this.isDragging = true;
        this.calculator.classList.add('dragging');
        const touch = e.touches[0];
        const rect = this.calculator.getBoundingClientRect();
        this.dragOffsetX = touch.clientX - rect.left;
        this.dragOffsetY = touch.clientY - rect.top;
    }
    
    doDraggingTouch(e) {
        if (!this.isDragging || e.touches.length !== 1) return;
        const touch = e.touches[0];
        const x = touch.clientX - this.dragOffsetX;
        const y = touch.clientY - this.dragOffsetY;
        this.calculator.style.left = `${x}px`;
        this.calculator.style.top = `${y}px`;
        this.calculator.style.transform = 'none';
    }
    
    handleKeyboard(e) {
        // Only react if calculator is shown
        if (!this.calculator || !this.calculator.classList.contains('show')) return;

        const key = e.key;
        if (/^[0-9]$/.test(key)) this.appendToDisplay(key);
        else if (key === '+') this.appendToDisplay('+');
        else if (key === '-') this.appendToDisplay('-');
        else if (key === '*') this.appendToDisplay('×');
        else if (key === '/') this.appendToDisplay('÷');
        else if (key === '.') this.appendToDisplay('.');
        else if (key === 'Enter') this.calculate();
        else if (key === 'Escape') this.closeCalculator();
        else if (key === 'Backspace') this.display.value = this.display.value.slice(0, -1);
    }

    show() {
        if (this.calculator) {
            this.calculator.classList.add('show');
            // Reset position to center if it's off screen
            const rect = this.calculator.getBoundingClientRect();
            if (rect.bottom < 0 || rect.top > window.innerHeight) {
                 this.calculator.style.top = '50%';
                 this.calculator.style.left = '50%';
                 this.calculator.style.transform = 'translate(-50%, -50%)';
            }
        }
    }
}

// Add this function to fix ALL touch events globally
function applyPassiveTouchListeners() {
    const originalAddEventListener = EventTarget.prototype.addEventListener;
    
    EventTarget.prototype.addEventListener = function(type, listener, options) {
        // Apply passive: true to ALL touch events by default
        if (type === 'touchstart' || type === 'touchmove' || type === 'touchend') {
            if (typeof options === 'boolean') {
                options = { capture: options, passive: true };
            } else if (typeof options === 'object') {
                if (!options.hasOwnProperty('passive')) {
                    options.passive = true;
                }
            } else {
                options = { passive: true };
            }
        }
        return originalAddEventListener.call(this, type, listener, options);
    };
}

// Global initialization
window.initCalculator = function() {
    // Apply passive touch listeners globally
    applyPassiveTouchListeners();
    
    window.calculator = new DraggableCalculator();

    // Attach to buttons reliably with passive listeners
    const attachListeners = () => {
        const elements = [
            'salesTableBody',
            'stock-history-section', 
            'expensesSection',
            'creditSalesSection',
            'currentStockSection'
        ];
        
        elements.forEach(id => {
            const element = document.getElementById(id);
            if (element) {
                element.addEventListener('dblclick', () => {
                    if (window.calculator) window.calculator.show();
                }, { passive: true });
            }
        });
    };

    // Run now or when DOM is ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', attachListeners, { passive: true });
    } else {
        attachListeners();
    }
};



// ===== customrecipt.js =====
function renderCustomReceiptFromSales(salesList, customer, date) {
    const tbody = document.getElementById('customReceiptProductTable');
    if (!tbody) return;

    // Clear all except filter row
    Array.from(tbody.children).forEach(row => {
        if (row.id !== 'customReceiptFilterRow') tbody.removeChild(row);
    });

    // 🗓️ Handle default date: today
    let targetDate;
    if (!date) {
        const today = new Date();
        const yyyy = today.getFullYear();
        const mm = String(today.getMonth() + 1).padStart(2, '0');
        const dd = String(today.getDate()).padStart(2, '0');
        date = `${yyyy}-${mm}-${dd}`;
        targetDate = today;
    } else {
        targetDate = new Date(date);
    }

    const dayName = targetDate.toLocaleDateString(currentLanguage, { weekday: 'long' });
    const formattedDate = targetDate.toLocaleDateString(currentLanguage, { year: 'numeric', month: 'long', day: 'numeric' });

    // Filter sales by the date
    const allSalesOnDate = salesList.filter(sale => {
        const saleDate = new Date(sale.dateSold);
        return saleDate.toISOString().slice(0, 10) === date;
    });

    // If no sales
    if (allSalesOnDate.length === 0) {
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td colspan="7" class="text-center py-4 text-gray-500">
                ${translate('no_sales_found_for_date')} ${customer ? `${translate('for')} '${customer}'` : ''} ${translate('on')} ${dayName}, ${formattedDate}
            </td>`;
        tbody.appendChild(tr);
        currentCustomReceiptData = null;
        return;
    }

    // ✅ Initialize receipt data
    currentCustomReceiptData = { customer, date, items: [] };

    // Render each sale with Add button
    allSalesOnDate.forEach(sale => {
        const tr = document.createElement('tr');

        // Format payment info
        let paymentInfo = sale.paymentType;
        if (sale.paymentType === translate('mobile_money') && sale.mobileMoneyType) {
            paymentInfo += ` (${sale.mobileMoneyType})`;
        } else if (sale.paymentType === translate('mixed_payment') && sale.hybridBreakdown) {
            const parts = [];
            if (sale.hybridBreakdown.cash > 0) parts.push(translate('cash'));
            if (sale.hybridBreakdown.mobile > 0) {
                parts.push(translate('mobile_money') + (sale.hybridBreakdown.mobileType ? ` (${sale.hybridBreakdown.mobileType})` : ''));
            }
            if (sale.hybridBreakdown.credit > 0) parts.push(translate('credit'));
            paymentInfo = `${translate('mixed')} (${parts.join(' + ')})`;
        }

        // Build table row
        tr.innerHTML = `
            <td class="px-2 py-1">
                <button class="bg-green-500 hover:bg-green-600 text-white px-2 py-1 rounded text-xs add-to-custom-receipt" 
                        data-sale-id="${sale.id}">
                    ${translate('add')}
                </button>
            </td>
            <td class="px-2 py-1">${sale.productName} (${translate(sale.type?.toLowerCase())})</td>
            <td class="px-2 py-1 text-center">${sale.quantity}</td>
            <td class="px-2 py-1 text-right">${formatCurrency(sale.price)}</td>
            <td class="px-2 py-1 text-sm text-blue-600">${paymentInfo}</td>
            <td class="px-2 py-1 text-gray-500 text-xs">
                ${sale.customerName ? `${translate('customer_colon')} ${sale.customerName}` : translate('no_customer')}
            </td>
        `;

        tbody.appendChild(tr);
    });

    // 🎯 Add event listeners for Add buttons

    // 🕒 Optional: show day and date on modal header
    const header = document.getElementById('customReceiptHeaderDate');
    if (header) {
        header.textContent = `${translate('sales_for')} ${dayName}, ${formattedDate}`;
    }
}

window.addCustomReceiptItem = function(saleId) {
    const sale = sales.find(s => s.id === saleId);
    if (!sale) return;
    const safeName = sale.productName.replace(/\s+/g, '_');
    const qtyInput = document.getElementById('customQtyInput_' + safeName + '_' + sale.id);
    const priceInput = document.getElementById('customPriceInput_' + safeName + '_' + sale.id);
    let qty = parseInt(qtyInput.value, 10) || 1;
    let price = parseFloat(priceInput.value);
    if (qty > sale.quantity) qty = sale.quantity;
    if (qty < 1) qty = 1;
    if (isNaN(price) || price < 0) price = sale.price || 0;

    customReceiptItems.push({
        id: sale.id,
        name: sale.productName,
        price: price,
        quantity: qty,
        subtotal: price,
        type: sale.type
    });

    renderCustomReceiptSelectedTable();
    updateCustomReceiptTotal();
};

window.removeCustomReceiptItem = function(saleId) {
    customReceiptItems = customReceiptItems.filter(i => i.id !== saleId);
    renderCustomReceiptSelectedTable();
    updateCustomReceiptTotal();
};

window.updateCustomReceiptQty = function(saleId, newQty) {
    const item = customReceiptItems.find(i => i.id === saleId);
    const sale = sales.find(s => s.id === saleId);
    if (item && sale) {
        let qty = parseInt(newQty, 10) || 1;
        if (qty > sale.quantity) qty = sale.quantity;
        if (qty < 1) qty = 1;
        item.quantity = qty;
        item.subtotal = item.price;
        renderCustomReceiptSelectedTable();
        updateCustomReceiptTotal();
    }
};

window.updateCustomReceiptPrice = function(saleId, newPrice) {
    const item = customReceiptItems.find(i => i.id === saleId);
    if (item) {
        let price = parseFloat(newPrice);
        if (isNaN(price) || price < 0) price = 0;
        item.price = price;
        item.subtotal = item.price;
        renderCustomReceiptSelectedTable();
        updateCustomReceiptTotal();
    }
};

function renderCustomReceiptProductTable() {
    const tbody = document.getElementById('customReceiptProductTable');
    if (!tbody) return;

    tbody.innerHTML = '';

    const customer = document.getElementById('customReceiptCustomerFilter').value.trim();
    const date = document.getElementById('customReceiptDateFilter').value;
    
    if (!date) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `<td colspan="7" class="text-center py-4 text-gray-500">${translate('select_date_first') || 'Please select a date first'}</td>`;
        tbody.appendChild(emptyRow);
        return;
    }

    // ========== FIX: Compare date parts only (ignore time) ==========
    const allSalesOnDate = sales.filter(s => {
        const saleDate = (s.dateSold || s.date_sold || '');
        // Extract just the date part for comparison
        const saleDateOnly = String(saleDate).split('T')[0].slice(0, 10);
        return saleDateOnly === date;
    });

    console.log('🔍 renderCustomReceiptProductTable:', {
        totalSales: sales.length,
        filteredCount: allSalesOnDate.length,
        targetDate: date,
        sampleSale: sales[0] ? { dateSold: sales[0].dateSold, date_sold: sales[0].date_sold } : null
    });

    if (allSalesOnDate.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `<td colspan="7" class="text-center py-4 text-gray-500">${translate('no_sales_for_selected_date') || 'No sales found for this date'}</td>`;
        tbody.appendChild(emptyRow);
        return;
    }

    // Track which sale IDs are already in the custom receipt
    const selectedSaleIds = new Set((currentCustomReceiptData?.items || []).map(item => item.id));

    allSalesOnDate.forEach(sale => {
        const tr = document.createElement('tr');
        tr.className = 'border-b hover:bg-gray-50';
        
        // Get payment info safely
        const paymentType = sale.paymentType || sale.payment_type || 'Cash';
        let paymentInfo = paymentType;
        
        if (paymentType === 'Mobile Money' && (sale.mobileMoneyType || sale.mobile_money_type)) {
            paymentInfo += ` (${sale.mobileMoneyType || sale.mobile_money_type})`;
        }

        const isAlreadyAdded = selectedSaleIds.has(sale.id);
        const productName = sale.productName || sale.product_name || 'Unknown';
        const quantity = sale.quantity || 1;
        const price = sale.price || sale.totalAmount || sale.total_amount || 0;
        const customerName = sale.customerName || sale.customer_name || '';

        const addButtonHtml = isAlreadyAdded
            ? `<button class="bg-gray-400 text-white px-2 py-1 rounded text-xs" disabled>${translate('added') || 'Added'}</button>`
            : `<button class="bg-green-500 hover:bg-green-600 text-white px-2 py-1 rounded text-xs add-to-custom-receipt" data-sale-id="${sale.id}">${translate('add') || 'Add'}</button>`;

        tr.innerHTML = `
            <td class="px-2 py-1">${addButtonHtml}</td>
            <td class="px-2 py-1">${productName} (${translate((sale.type || 'product').toLowerCase()) || 'Product'})</td>
            <td class="px-2 py-1 text-center">${quantity}</td>
            <td class="px-2 py-1 text-right">${typeof formatCurrency === 'function' ? formatCurrency(price) : price}</td>
            <td class="px-2 py-1 text-right">${typeof formatCurrency === 'function' ? formatCurrency(price) : price}</td>
            <td class="px-2 py-1 text-sm text-blue-600">${paymentInfo}</td>
            <td class="px-2 py-1 text-gray-500 text-xs">
                ${customerName ? `${translate('customer_colon') || 'Customer:'} ${customerName}` : translate('no_customer') || 'No customer'}
            </td>
        `;
        tbody.appendChild(tr);
    });

    // Add event listeners to "Add" buttons
    document.querySelectorAll('.add-to-custom-receipt').forEach(btn => {
        btn.addEventListener('click', function() {
            const saleId = this.getAttribute('data-sale-id');
            const sale = sales.find(s => s.id === saleId);
            if (!sale) return;

            const item = {
                id: sale.id,
                name: sale.productName || sale.product_name,
                type: sale.type || 'product',
                quantity: sale.quantity || 1,
                price: sale.price || sale.totalAmount || sale.total_amount || 0,
                paymentType: sale.paymentType || sale.payment_type,
                mobileMoneyType: sale.mobileMoneyType || sale.mobile_money_type,
                hybridBreakdown: sale.hybridBreakdown || sale.hybrid_breakdown,
                customerName: sale.customerName || sale.customer_name || customer,
                advancePaymentDate: sale.advancePaymentDate || sale.advance_payment_date,
                advancePayment: sale.advancePayment || sale.advance_payment || 0,
                customerPhoneNumber:sale.customer_phone || ''
            };
            
            if (!currentCustomReceiptData) {
                currentCustomReceiptData = { customer, date, items: [] };
            }

            if (!currentCustomReceiptData.items.some(i => i.id === item.id)) {
                currentCustomReceiptData.items.push(item);
                if (typeof renderCustomReceiptSelectedTable === 'function') renderCustomReceiptSelectedTable();
                
                this.disabled = true;
                this.textContent = translate('added') || 'Added';
                this.classList.remove('bg-green-500', 'hover:bg-green-600');
                this.classList.add('bg-gray-400', 'cursor-not-allowed');
            }
        });
    });

    // Update header date
    const header = document.getElementById('customReceiptHeaderDate');
    if (header) {
        const targetDate = new Date(date + 'T00:00:00');
        const dayName = targetDate.toLocaleDateString('en-US', { weekday: 'long' });
        const formattedDate = targetDate.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
        header.textContent = `${translate('sales_for') || 'Sales for'} ${dayName}, ${formattedDate}`;
    }
}

function renderCustomReceiptSelectedTable() {
    const tbody = document.getElementById('customReceiptSelectedTable');
    if (!tbody) {
        console.error('customReceiptSelectedTable element not found');
        return;
    }
    
    tbody.innerHTML = '';

    // Use the correct data source
    const items = currentCustomReceiptData?.items || [];
    
    if (!items || items.length === 0) {
        const emptyRow = document.createElement('tr');
        emptyRow.innerHTML = `
            <td colspan="5" class="text-center text-gray-500 py-4">
                ${translate('no_items_selected_yet')}
            </td>`;
        tbody.appendChild(emptyRow);
        return;
    }

    items.forEach((item, index) => {
        const subtotal = (item.price || 0) * (item.quantity || 1);
        const tr = document.createElement('tr');
        tr.className = 'hover:bg-gray-50 border-b';
        tr.innerHTML = `
            <td class="px-4 py-2 text-sm">${item.name} (${item.type ? translate(item.type.toLowerCase()) : translate('product')})</td>
            <td class="px-4 py-2 text-sm text-center">${item.quantity || 1}</td>
            <td class="px-4 py-2 text-sm text-right">${formatCurrency(item.price || 0)}</td>
            <td class="px-4 py-2 text-sm text-right font-semibold">${formatCurrency(subtotal)}</td>
            <td class="px-4 py-2 text-center">
                <button class="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-xs remove-custom-item" 
                        data-index="${index}">
                    ${translate('remove')}
                </button>
            </td>
        `;
        tbody.appendChild(tr);
    });

    // Add event listeners to remove buttons
    document.querySelectorAll('.remove-custom-item').forEach(btn => {
        btn.addEventListener('click', function() {
            const index = parseInt(this.getAttribute('data-index'));
            removeCustomReceiptItem(index);
        });
    });

    updateCustomReceiptTotal();
}

function removeCustomReceiptItem(index) {
    if (currentCustomReceiptData?.items) {
        currentCustomReceiptData.items.splice(index, 1);
        renderCustomReceiptSelectedTable();
        renderCustomReceiptProductTable(); // Re-enable the "Add" button
    }
}

function updateCustomReceiptTotal() {
    const items = currentCustomReceiptData?.items || [];
    const total = items.reduce((sum, item) => {
        return sum + ((item.price || 0));
    }, 0);
    
    const totalElement = document.getElementById('customReceiptTotal');
    if (totalElement) {
        totalElement.textContent = formatCurrency(Math.round(total));
    }
}

